<script>
(() => {

  function initNitrogenHeader(root) {

    if (!root || root.dataset.nitrogenHeaderReady === 'true') {
      return;
    }


    root.dataset.nitrogenHeaderReady = 'true';


    const openButton =
      root.querySelector('[data-n2-open]');


    const mobileMenu =
      root.querySelector('[data-n2-menu]');


    const closeButtons =
      root.querySelectorAll('[data-n2-close]');


    const wishlistLink =
      root.querySelector('[data-n2-wishlist-link]');

    const wishlistCount =
      root.querySelector('[data-n2-wishlist-count]');

    const wishlistEndpoint = '/apps/wishlist';
    const wishlistGuestKey = 'lg_aurelia_guest_wishlist_v1';

    function normaliseWishlistItems(items) {
      if (!Array.isArray(items)) return [];

      return Array.from(
        new Set(
          items
            .map((item) => String(item || '').trim())
            .filter(Boolean)
            .map((item) => {
              if (item.startsWith('gid://shopify/Product/')) {
                return item;
              }

              if (/^\d+$/.test(item)) {
                return 'gid://shopify/Product/' + item;
              }

              return null;
            })
            .filter(Boolean)
        )
      );
    }

    function readGuestWishlist() {
      try {
        return normaliseWishlistItems(
          JSON.parse(
            window.localStorage.getItem(wishlistGuestKey) || '[]'
          )
        );
      } catch (error) {
        return [];
      }
    }

    function writeGuestWishlist(items) {
      const cleanItems = normaliseWishlistItems(items);

      try {
        window.localStorage.setItem(
          wishlistGuestKey,
          JSON.stringify(cleanItems)
        );
      } catch (error) {}

      return cleanItems;
    }

    function renderWishlistCount(items) {
      if (!wishlistLink || !wishlistCount) return;

      const cleanItems = normaliseWishlistItems(items);
      const count = cleanItems.length;

      if (count > 0) {
        wishlistCount.textContent = String(count);
        wishlistCount.hidden = false;
        wishlistLink.classList.add('is-active');
        wishlistLink.setAttribute(
          'aria-label',
          'Wishlist, ' + count + (count === 1 ? ' item' : ' items')
        );
      } else {
        wishlistCount.textContent = '';
        wishlistCount.hidden = true;
        wishlistLink.classList.remove('is-active');
        wishlistLink.setAttribute('aria-label', 'Wishlist');
      }
    }

    function broadcastWishlist(items, loggedIn) {
      const cleanItems = normaliseWishlistItems(items);

      window.dispatchEvent(
        new CustomEvent('lg-aurelia:wishlist-updated', {
          detail: {
            count: cleanItems.length,
            wishlist: cleanItems,
            loggedIn: Boolean(loggedIn)
          }
        })
      );
    }

    async function wishlistRequest(method, body) {
      const options = {
        method,
        headers: {
          'Accept': 'application/json'
        },
        credentials: 'same-origin'
      };

      if (body) {
        options.headers['Content-Type'] = 'application/json';
        options.body = JSON.stringify(body);
      }

      const response = await fetch(wishlistEndpoint, options);

      if (!response.ok) {
        throw new Error('Wishlist request failed with status ' + response.status);
      }

      const data = await response.json();

      if (!data || data.ok !== true) {
        throw new Error(data?.error || 'Wishlist request failed.');
      }

      return data;
    }

    async function initialiseWishlistHeader() {
      if (!wishlistLink || !wishlistCount) return;

      const guestItems = readGuestWishlist();

      try {
        let data = await wishlistRequest('GET');

        if (data.loggedIn) {
          let mergedSuccessfully = true;

          for (const gid of guestItems) {
            const accountItems = normaliseWishlistItems(data.wishlist);

            if (accountItems.includes(gid)) {
              continue;
            }

            try {
              data = await wishlistRequest('POST', {
                action: 'add',
                productId: gid.split('/').pop()
              });
            } catch (error) {
              mergedSuccessfully = false;
              console.warn('LG Aurelia wishlist guest merge paused:', error);
              break;
            }
          }

          if (mergedSuccessfully && guestItems.length > 0) {
            writeGuestWishlist([]);
          }

          const accountItems = normaliseWishlistItems(data.wishlist);
          renderWishlistCount(accountItems);
          broadcastWishlist(accountItems, true);
          return;
        }
      } catch (error) {
        console.warn('LG Aurelia wishlist header using browser fallback:', error);
      }

      renderWishlistCount(guestItems);
      broadcastWishlist(guestItems, false);
    }

    if (wishlistLink && wishlistCount) {
      window.addEventListener(
        'lg-aurelia:wishlist-updated',
        function(event) {
          if (!root.isConnected || !event.detail) return;

          if (Array.isArray(event.detail.wishlist)) {
            renderWishlistCount(event.detail.wishlist);
          } else {
            const count = Number(event.detail.count || 0);

            if (count > 0) {
              wishlistCount.textContent = String(count);
              wishlistCount.hidden = false;
              wishlistLink.classList.add('is-active');
            } else {
              wishlistCount.textContent = '';
              wishlistCount.hidden = true;
              wishlistLink.classList.remove('is-active');
            }
          }
        }
      );

      initialiseWishlistHeader();
    }


    if (!openButton || !mobileMenu) {
      return;
    }


    function openMenu() {

      mobileMenu.classList.add('is-open');

      openButton.setAttribute(
        'aria-expanded',
        'true'
      );

      document.documentElement.style.overflow =
        'hidden';

    }


    function closeMenu() {

      mobileMenu.classList.remove('is-open');

      openButton.setAttribute(
        'aria-expanded',
        'false'
      );

      document.documentElement.style.overflow =
        '';

    }


    openButton.addEventListener(
      'click',
      openMenu
    );


    closeButtons.forEach((button) => {

      button.addEventListener(
        'click',
        closeMenu
      );

    });


    document.addEventListener(
      'keydown',
      (event) => {

        if (event.key === 'Escape') {
          closeMenu();
        }

      }
    );


    window.addEventListener(
      'resize',
      () => {

        if (window.innerWidth > 989) {
          closeMenu();
        }

      }
    );

  }


  const section =
    document.getElementById(
      'NitrogenHeader-template--30044023456091__nitrogen_header_VwNjfn'
    );


  initNitrogenHeader(section);


  document.addEventListener(
    'shopify:section:load',
    function(event) {

      const loaded =
        event.target.querySelector
        ? event.target.querySelector(
            '#NitrogenHeader-template--30044023456091__nitrogen_header_VwNjfn'
          )
        : null;


      if (loaded) {
        initNitrogenHeader(loaded);
      }

    }
  );

})();
</script>


