  const paymentTermsVariant = section.querySelector('[data-payment-terms-variant]');
  const dynamicCheckout = section.querySelector('[data-dynamic-checkout]');
  const productForm = section.querySelector('.n-product__form');
  const wishlistButton = section.querySelector('[data-wishlist-button]');
  const wishlistLabel = section.querySelector('[data-wishlist-label]');

