            (track.clientWidth / 2);

          let closestIndex = 0;
          let closestDistance = Infinity;

          slides.forEach((slide, index) => {
            const slideCentre =
              slide.offsetLeft +
              (slide.offsetWidth / 2);

            const distance =
              Math.abs(
                centre -
                slideCentre
              );

            if (distance < closestDistance) {
              closestDistance = distance;
              closestIndex = index;
            }
          });

          updateActiveMedia(closestIndex);

          ticking = false;
        });
      },
      { passive: true }
    );
