  });

  function updateVariantMetafields(variantId) {
    if (!variantId || variantMetafieldBlocks.length === 0) return;

    variantMetafieldBlocks.forEach((block) => {
      const content = block.querySelector('[data-variant-metafield-content]');
      const template = block.querySelector(
        '[data-variant-metafield-template="' + variantId + '"]'
      );

      const html = template
        ? template.innerHTML.trim()
        : '';

      if (content) {
        content.innerHTML = html;
      }

      if (html) {
        block.hidden = false;
      } else {
        block.hidden = true;
        block.removeAttribute('open');
      }
    });
  }


  function updateVariant() {
    if (!variantSelect) return;

    const option =
      variantSelect.options[
        variantSelect.selectedIndex
      ];

    if (!option) return;

    updateVariantMetafields(option.value);

    if (paymentTermsVariant) {
      paymentTermsVariant.value = option.value;

      paymentTermsVariant.dispatchEvent(
        new Event(
          'change',
          { bubbles: true }
        )
      );
    }

    const price =
      Number(option.dataset.price || 0);

    const compare =
      Number(option.dataset.comparePrice || 0);

    const isAvailable =
      option.dataset.available === 'true';

    if (priceElement) {
      priceElement.textContent =
        formatMoney(price);
    }

    if (compareElement) {
      if (compare > price) {
        compareElement.textContent =
          formatMoney(compare);

        compareElement.classList.remove(
          'is-hidden'
        );
      } else {
        compareElement.textContent = '';

        compareElement.classList.add(
          'is-hidden'
        );
      }
    }

    if (availability) {
      availability.classList.toggle(
        'is-sold-out',
        !isAvailable
      );
    }

    if (availabilityText) {
      availabilityText.textContent =
        isAvailable
          ? "Available"
          : "Sold Out";
    }

    if (addButton) {
      addButton.disabled = !isAvailable;
    }

    if (addButtonText) {
      addButtonText.textContent =
        isAvailable
          ? "Add to Bag"
          : "Sold Out";
    }

    if (dynamicCheckout) {
      dynamicCheckout.hidden = !(
        allProductOptionsChosen() &&
        isAvailable
      );
    }

    const mediaId =
      option.dataset.mediaId;

    if (mediaId) {
      const mediaIndex =
        slides.findIndex(
          slide =>
            String(slide.dataset.mediaId) ===
            String(mediaId)
        );

      if (mediaIndex >= 0) {
        goToMedia(mediaIndex);
      }
    }

    try {
      const url =
        new URL(window.location.href);

      url.searchParams.set(
        'variant',
        option.value
      );

      window.history.replaceState(
        {},
        '',
        url.toString()
      );
    } catch (error) {}
  }

  function refreshOptionPlaceholderStyles() {
    optionSelects.forEach((select) => {
      select.classList.toggle(
        'is-placeholder',
        !select.value
      );
    });
  }


  function allProductOptionsChosen() {
    return (
      optionSelects.length > 0 &&
      optionSelects.every((select) => Boolean(select.value))
    );
  }


  function setAwaitingOptionSelection() {
    refreshOptionPlaceholderStyles();

    if (availability) {
      availability.classList.remove('is-sold-out');
    }

    if (availabilityText) {
      availabilityText.textContent =
        "Choose an option";
    }

    if (addButton) {
      addButton.disabled = true;
    }

    if (addButtonText) {
      addButtonText.textContent =
        "Choose an option";
    }

    if (dynamicCheckout) {
      dynamicCheckout.hidden = true;
    }
  }


  function findVariantForCurrentOptions() {
    if (!variantSelect || !allProductOptionsChosen()) return null;

    const variants =
      Array.from(variantSelect.options);

    return variants.find((variantOption) => {
      return optionSelects.every((select) => {
        const position =
          select.dataset.optionPosition;

        return (
          variantOption.getAttribute(
            'data-option-' + position
          ) ===
          select.value
        );
      });
    }) || null;
  }


  function showUnavailableCombination() {
    if (availability) {
      availability.classList.add('is-sold-out');
    }

    if (availabilityText) {
      availabilityText.textContent =
        "Sold Out";
    }

    if (addButton) {
      addButton.disabled = true;
    }

    if (addButtonText) {
      addButtonText.textContent =
        "Sold Out";
    }

    if (dynamicCheckout) {
      dynamicCheckout.hidden = true;
    }
  }


  function selectVariantFromOptions() {
    refreshOptionPlaceholderStyles();

    if (!allProductOptionsChosen()) {
      setAwaitingOptionSelection();
      return;
    }

    const matchingVariant =
      findVariantForCurrentOptions();

    if (!matchingVariant) {
      showUnavailableCombination();
      return;
    }

    variantSelect.value =
      matchingVariant.value;

    variantSelect.dispatchEvent(
      new Event(
        'change',
        { bubbles: true }
      )
    );
  }


  if (variantSelect) {
    /*
      Deliberately do NOT preselect Shopify's first/current variant in the
      visible dropdowns. Each selector starts with a non-purchasable
      placeholder such as “Please choose ring size”.
    */
    setAwaitingOptionSelection();

    variantSelect.addEventListener(
      'change',
      function() {
        updateVariant();

        const selectedVariantOption =
          variantSelect.options[
            variantSelect.selectedIndex
          ];

        const isAvailable =
          Boolean(selectedVariantOption) &&
          selectedVariantOption.dataset.available === 'true';

        if (dynamicCheckout) {
          dynamicCheckout.hidden = !(
            allProductOptionsChosen() &&
            isAvailable
          );
        }
      }
    );

    optionSelects.forEach((select) => {
      select.addEventListener(
        'change',
        function() {
          selectVariantFromOptions();
        }
      );
    });

    if (productForm) {
      productForm.addEventListener(
        'submit',
        function(event) {
          if (allProductOptionsChosen()) return;

          event.preventDefault();

          const firstUnchosen =
            optionSelects.find((select) => !select.value);

          if (firstUnchosen) {
            firstUnchosen.focus();
            firstUnchosen.reportValidity();
          }
        }
      );
    }
  } else {
    const hiddenVariantInput = section.querySelector('[data-variant-id]');

    if (hiddenVariantInput) {
      updateVariantMetafields(hiddenVariantInput.value);
    }
  }

  if (qtyMinus && qtyInput) {
    qtyMinus.addEventListener(
      'click',
      function() {
        const current =
          Math.max(
            1,
            Number(qtyInput.value || 1)
          );

        qtyInput.value =
          Math.max(
            1,
            current - 1
          );
      }
    );
  }

  if (qtyPlus && qtyInput) {
    qtyPlus.addEventListener(
      'click',
      function() {
        const current =
          Math.max(
            1,
            Number(qtyInput.value || 1)
          );

        qtyInput.value =
          current + 1;
      }
    );
  }

  function normaliseWishlistItems(items) {
    if (!Array.isArray(items)) return [];

    return Array.from(
      new Set(
        items
          .map((item) => String(item || '').trim())
          .filter(Boolean)
          .map((item) => {
            if (item.startsWith('gid://shopify/Product/')) {
              return item;
            }

            if (/^\d+$/.test(item)) {
              return 'gid://shopify/Product/' + item;
            }

            return null;
          })
          .filter(Boolean)
      )
    );
  }

  function readGuestWishlist() {
    try {
      return normaliseWishlistItems(
        JSON.parse(
          window.localStorage.getItem(wishlistGuestKey) || '[]'
        )
      );
    } catch (error) {
      return [];
    }
  }

  function writeGuestWishlist(items) {
    const cleanItems = normaliseWishlistItems(items);

    try {
      window.localStorage.setItem(
        wishlistGuestKey,
        JSON.stringify(cleanItems)
      );
    } catch (error) {}

    return cleanItems;
  }

  function renderWishlistButton() {
    if (!wishlistButton) return;

    const saved = wishlistItems.includes(wishlistProductGid);

    wishlistButton.classList.toggle('is-saved', saved);
    wishlistButton.classList.toggle('is-loading', wishlistBusy);
    wishlistButton.setAttribute('aria-pressed', saved ? 'true' : 'false');
    wishlistButton.disabled = wishlistBusy;

    if (wishlistLabel) {
      wishlistLabel.textContent = wishlistBusy
        ? 'Updating…'
        : saved
          ? "Saved to Wishlist"
          : "Add to Wishlist";
    }
  }

  function broadcastWishlist() {
    window.dispatchEvent(
      new CustomEvent('lg-aurelia:wishlist-updated', {
        detail: {
          count: wishlistItems.length,
          wishlist: wishlistItems.slice(),
          loggedIn: wishlistLoggedIn
        }
      })
    );
  }

  function useGuestWishlist() {
    wishlistBackendAvailable = false;
    wishlistLoggedIn = false;
    wishlistItems = readGuestWishlist();

    renderWishlistButton();
    broadcastWishlist();
  }

  async function wishlistRequest(method, body) {
    const options = {
      method,
      headers: {
        'Accept': 'application/json'
      },
      credentials: 'same-origin'
    };

    if (body) {
      options.headers['Content-Type'] = 'application/json';
      options.body = JSON.stringify(body);
    }

    const response = await fetch(wishlistEndpoint, options);

    if (!response.ok) {
      throw new Error('Wishlist request failed with status ' + response.status);
    }

    const data = await response.json();

    if (!data || data.ok !== true) {
      throw new Error(data?.error || 'Wishlist request failed.');
    }

    return data;
  }

  async function initialiseWishlist() {
    if (!wishlistButton) return;

    wishlistBusy = true;
    renderWishlistButton();

    try {
      let data = await wishlistRequest('GET');

      wishlistBackendAvailable = true;

      if (data.loggedIn) {
        wishlistLoggedIn = true;
        wishlistItems = normaliseWishlistItems(data.wishlist);
      } else {
        wishlistLoggedIn = false;
        wishlistItems = readGuestWishlist();
      }
    } catch (error) {
      console.warn('LG Aurelia wishlist using browser fallback:', error);
      wishlistBackendAvailable = false;
      wishlistLoggedIn = false;
      wishlistItems = readGuestWishlist();
    }

    wishlistBusy = false;
    renderWishlistButton();
    broadcastWishlist();
  }

  async function toggleWishlist() {
    if (!wishlistButton || wishlistBusy) return;

    const isSaved = wishlistItems.includes(wishlistProductGid);
    const action = isSaved ? 'remove' : 'add';

    wishlistBusy = true;
    renderWishlistButton();

    if (wishlistBackendAvailable && wishlistLoggedIn) {
      try {
        const data = await wishlistRequest('POST', {
          action,
          productId: wishlistProductId
        });

        wishlistItems = normaliseWishlistItems(data.wishlist);
        wishlistLoggedIn = Boolean(data.loggedIn);
      } catch (error) {
        console.warn('LG Aurelia wishlist could not update the account:', error);
      }
    } else {
      wishlistItems = isSaved
        ? wishlistItems.filter((gid) => gid !== wishlistProductGid)
        : normaliseWishlistItems([...wishlistItems, wishlistProductGid]);

      wishlistItems = writeGuestWishlist(wishlistItems);
    }

    wishlistBusy = false;
    renderWishlistButton();
    broadcastWishlist();
  }

  if (wishlistButton) {
    wishlistButton.addEventListener('click', toggleWishlist);

    window.addEventListener(
      'lg-aurelia:wishlist-updated',
      function(event) {
        if (!event.detail || !Array.isArray(event.detail.wishlist)) return;

        wishlistItems = normaliseWishlistItems(event.detail.wishlist);
        wishlistLoggedIn = Boolean(event.detail.loggedIn);
        renderWishlistButton();
      }
    );

    initialiseWishlist();
  }

  if (notice) {
    window.setTimeout(function() {
      notice.classList.add('is-visible');
    }, 350);
  }

  if (noticeClose && notice) {
    noticeClose.addEventListener(
      'click',
      function() {
        notice.classList.remove('is-visible');
      }
    );
  }
})();
</script>




