<script>
(function() {

  function initialiseRecommendations(section) {

    if (!section || section.dataset.ready === 'true') return;

    section.dataset.ready = 'true';

    const url = section.dataset.url;

    if (!url) return;


    function initialiseCarousel() {

      const track =
        section.querySelector('[data-recs-track]');

      const previous =
        section.querySelector('[data-recs-prev]');

      const next =
        section.querySelector('[data-recs-next]');

      if (!track) return;


      function cardStep() {

        const card =
          track.querySelector('.n-recs__card');

