          startX = event.clientX;

          startScrollLeft =
            track.scrollLeft;

          track.classList.add(
            'is-dragging'
          );

          track.setPointerCapture(
            event.pointerId
          );

        }
      );


      track.addEventListener(
        'pointermove',
        function(event) {

          if (!dragging) return;

          const distance =
