<script>
(function() {

  const section =
    document.getElementById(
      'NitrogenNewIn-template--30044023456091__new_in_product_page_collection_pgUzqL'
    );

  if (!section || section.dataset.ready === 'true') return;

  section.dataset.ready = 'true';

  const track =
    section.querySelector('[data-new-in-track]');

  const previous =
    section.querySelector('[data-new-in-prev]');

  const next =
    section.querySelector('[data-new-in-next]');

  if (!track) return;


  function cardStep() {

    const card =
      track.querySelector('.n-new-in__card');

    if (!card) return track.clientWidth;

    const styles =
      window.getComputedStyle(track);

    const gap =
      parseFloat(
        styles.columnGap ||
        styles.gap ||
        0
      );

    return (
      card.getBoundingClientRect().width +
      gap
    );
  }


  if (previous) {
    previous.addEventListener(
      'click',
      function() {
        track.scrollBy({
          left: -cardStep(),
          behavior: 'smooth'
        });
      }
    );
  }


  if (next) {
    next.addEventListener(
      'click',
      function() {
        track.scrollBy({
          left: cardStep(),
          behavior: 'smooth'
        });
      }
    );
  }


  let dragging = false;
  let startX = 0;
  let startScrollLeft = 0;


  track.addEventListener(
    'pointerdown',
    function(event) {

      if (event.pointerType === 'touch') return;

      dragging = true;

      startX = event.clientX;

      startScrollLeft =
        track.scrollLeft;

      track.classList.add(
        'is-dragging'
      );

      track.setPointerCapture(
        event.pointerId
      );

    }
  );


  track.addEventListener(
    'pointermove',
    function(event) {

      if (!dragging) return;

      const distance =
        event.clientX - startX;

      track.scrollLeft =
        startScrollLeft - distance;

    }
  );


  function stopDragging(event) {

    if (!dragging) return;

    dragging = false;

    track.classList.remove(
      'is-dragging'
    );

    try {
      track.releasePointerCapture(
        event.pointerId
      );
    } catch (error) {}

  }


  track.addEventListener(
    'pointerup',
    stopDragging
  );

  track.addEventListener(
    'pointercancel',
    stopDragging
  );

  track.addEventListener(
    'pointerleave',
    function(event) {

      if (
        dragging &&
        event.buttons === 0
      ) {
        stopDragging(event);
      }

    }
  );

})();
</script>



